import sqlite3
import json
from itertools import combinations, permutations

MAP_WIDTH = 44
MAP_HEIGHT = 26

conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cursor = conn.cursor()

# Load all tile data
cursor.execute("SELECT ID, TerrainType, IsImpassable FROM Plots ORDER BY ID")
plots = {}
for row in cursor.fetchall():
    pid = row[0]
    x = pid % MAP_WIDTH
    y = pid // MAP_WIDTH
    plots[(x, y)] = {'terrain': row[1], 'impassable': row[2]}

cursor.execute("SELECT ID, FeatureType FROM PlotFeatures")
features = {}
for row in cursor.fetchall():
    x = row[0] % MAP_WIDTH
    y = row[0] // MAP_WIDTH
    features[(x, y)] = row[1]

cursor.execute("SELECT * FROM PlotRivers")
rivers_raw = cursor.fetchall()
conn.close()

def get_neighbors(x, y):
    if y % 2 == 0:
        return [(x+1,y),(x-1,y),(x,y+1),(x-1,y+1),(x,y-1),(x-1,y-1)]
    else:
        return [(x+1,y),(x-1,y),(x+1,y+1),(x,y+1),(x+1,y-1),(x,y-1)]

def get_neighbor_dict(x, y):
    if y % 2 == 0:
        return {'E':(x+1,y),'W':(x-1,y),'NE':(x,y+1),'NW':(x-1,y+1),'SE':(x,y-1),'SW':(x-1,y-1)}
    else:
        return {'E':(x+1,y),'W':(x-1,y),'NE':(x+1,y+1),'NW':(x,y+1),'SE':(x+1,y-1),'SW':(x,y-1)}

# Build river edges
river_edges = set()
for r in rivers_raw:
    pid = r[0]
    x = pid % MAP_WIDTH
    y = pid // MAP_WIDTH
    if y % 2 == 0:
        nb = {'NE':(x,y+1),'W':(x-1,y),'NW':(x-1,y+1)}
    else:
        nb = {'NE':(x+1,y+1),'W':(x-1,y),'NW':(x,y+1)}
    if r[1]: river_edges.add(frozenset({(x,y), nb['NE']}))
    if r[2]: river_edges.add(frozenset({(x,y), nb['W']}))
    if r[3]: river_edges.add(frozenset({(x,y), nb['NW']}))

def tile_has_river(x, y):
    for nx, ny in get_neighbors(x, y):
        if frozenset({(x,y),(nx,ny)}) in river_edges:
            return True
    return False

def river_between(t1, t2):
    return frozenset({t1, t2}) in river_edges

def hex_distance(x1, y1, x2, y2):
    def to_cube(x, y):
        cx = x - (y - (y & 1)) // 2
        cz = y
        cy = -cx - cz
        return cx, cy, cz
    c1 = to_cube(x1, y1)
    c2 = to_cube(x2, y2)
    return max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2]))

def is_land(tile):
    if tile not in plots:
        return False
    t = plots[tile]['terrain']
    return t not in ('TERRAIN_OCEAN', 'TERRAIN_COAST') and 'MOUNTAIN' not in t

def is_coast(tile):
    if tile not in plots:
        return False
    return plots[tile]['terrain'] == 'TERRAIN_COAST'

def is_mountain(tile):
    if tile not in plots:
        return False
    return 'MOUNTAIN' in plots[tile]['terrain']

def is_floodplains(tile):
    return features.get(tile, '') == 'FEATURE_FLOODPLAINS_PLAINS'

# Identify all valid tiles
land_tiles = [t for t in plots if is_land(t)]
coast_tiles = [t for t in plots if is_coast(t)]
mountains = [t for t in plots if is_mountain(t)]

# Population 9 -> floor(9/3)+1 = 4 specialty districts
NUM_SPECIALTY = 4

# Specialty districts to consider:
# CAMPUS, HOLY_SITE, COMMERCIAL_HUB, INDUSTRIAL_ZONE, THEATER_SQUARE,
# ENTERTAINMENT_COMPLEX, ENCAMPMENT, GOVERNMENT_PLAZA, HARBOR, PRESERVE
# Non-specialty: AQUEDUCT, DAM

# Calculate adjacency bonus for a district given a placement
def calc_adjacency(district_type, tile, placement, city_center):
    """
    placement: dict of district_type -> tile
    city_center: (x, y)
    """
    x, y = tile
    nbs = get_neighbors(x, y)

    adj_mountains = 0
    adj_geothermal = 0
    adj_reefs = 0
    adj_forests = 0
    adj_jungles = 0
    adj_districts = 0  # count of adjacent district tiles (including city center, aqueduct, dam)
    adj_natural_wonders = 0
    has_river = tile_has_river(x, y)
    adj_aqueduct = 0
    adj_dam = 0
    adj_city_center = 0
    adj_entertainment = 0
    adj_harbor = 0
    adj_gov_plaza = 0

    for nx, ny in nbs:
        nt = (nx, ny)
        if nt not in plots:
            continue

        terrain = plots[nt]['terrain']
        feat = features.get(nt, '')

        if 'MOUNTAIN' in terrain:
            adj_mountains += 1

        # Features (note: if we place a district on a tile, the feature is removed)
        # So only count features on tiles that don't have a district placed
        if nt not in placement.values() and nt != city_center:
            if feat == 'FEATURE_GEOTHERMAL_FISSURE':
                adj_geothermal += 1
            if feat == 'FEATURE_REEF':
                adj_reefs += 1
            if feat == 'FEATURE_FOREST':
                adj_forests += 1
            if feat == 'FEATURE_JUNGLE':
                adj_jungles += 1

        # Count adjacent districts
        if nt == city_center:
            adj_city_center += 1
            adj_districts += 1

        for dtype, dtile in placement.items():
            if dtile == nt and dtype != district_type:
                adj_districts += 1
                if dtype == 'AQUEDUCT':
                    adj_aqueduct += 1
                if dtype == 'DAM':
                    adj_dam += 1
                if dtype == 'ENTERTAINMENT_COMPLEX':
                    adj_entertainment += 1
                if dtype == 'HARBOR':
                    adj_harbor += 1
                if dtype == 'GOVERNMENT_PLAZA':
                    adj_gov_plaza += 1

    score = 0

    if district_type == 'CAMPUS':
        score += adj_mountains  # +1 per mountain
        score += adj_geothermal  # +1 per geothermal fissure
        score += adj_reefs  # +1 per reef
        score += adj_jungles // 2  # +1 per 2 jungles
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'HOLY_SITE':
        score += adj_mountains  # +1 per mountain
        score += adj_natural_wonders * 2  # +2 per natural wonder
        score += adj_forests // 2  # +1 per 2 forests
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'THEATER_SQUARE':
        # +2 per wonder (none on this map)
        score += adj_entertainment  # +1 per Entertainment Complex
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'COMMERCIAL_HUB':
        if has_river:
            score += 2  # +2 for being adjacent to river
        score += adj_harbor * 2  # +2 per adjacent harbor
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'HARBOR':
        score += adj_city_center * 2  # +2 per adjacent city center
        # +1 per coastal resource (none on this map)
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'INDUSTRIAL_ZONE':
        # +1 per mine/quarry (none on this map)
        score += adj_aqueduct  # +1 per aqueduct
        score += adj_dam  # +1 per dam
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'ENTERTAINMENT_COMPLEX':
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'GOVERNMENT_PLAZA':
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'ENCAMPMENT':
        score += adj_districts // 2  # +1 per 2 districts

    elif district_type == 'AQUEDUCT':
        score += 0  # Aqueduct doesn't get adjacency bonuses itself

    elif district_type == 'DAM':
        score += 0  # Dam doesn't get adjacency bonuses itself

    elif district_type == 'PRESERVE':
        score += 0  # Preserve doesn't get standard adjacency

    return score

def is_valid_placement(district_type, tile, placement, city_center):
    x, y = tile

    # Check tile is not already used
    if tile == city_center:
        return False
    for dtype, dtile in placement.items():
        if dtile == tile:
            return False

    # Check within 3 tiles of city center
    cx, cy = city_center
    if hex_distance(x, y, cx, cy) > 3:
        return False

    # District-specific checks
    if district_type == 'HARBOR':
        if not is_coast(tile):
            return False
        # Harbor must be adjacent to land (city must work it)
    elif district_type == 'AQUEDUCT':
        # Must be adjacent to city center
        nbs = get_neighbors(x, y)
        if city_center not in nbs:
            return False
        # Must also be adjacent to mountain, river, lake, or oasis
        has_water_source = False
        for nx, ny in nbs:
            if (nx, ny) in plots and is_mountain((nx, ny)):
                has_water_source = True
            if tile_has_river(x, y):
                has_water_source = True
        if not has_water_source:
            return False
        # Must be on land
        if not is_land(tile):
            return False
    elif district_type == 'DAM':
        # Must be on floodplains
        if not is_floodplains(tile):
            return False
        # Must be adjacent to river
        if not tile_has_river(x, y):
            return False
        if not is_land(tile):
            return False
    elif district_type == 'ENCAMPMENT':
        # Cannot be adjacent to city center
        nbs = get_neighbors(x, y)
        if city_center in nbs:
            return False
        if not is_land(tile):
            return False
    else:
        # Standard district - must be on land
        if not is_land(tile):
            return False

    return True

def total_adjacency(placement, city_center):
    total = 0
    bonuses = {}
    for dtype, tile in placement.items():
        bonus = calc_adjacency(dtype, tile, placement, city_center)
        bonuses[dtype] = bonus
        total += bonus
    return total, bonuses

# Strategy: try different combinations of district types and positions
# With pop 9, we get 4 specialty districts
# Plus non-specialty: Aqueduct, Dam (both give +1 to Industrial Zone)

# Let's consider the best district types for this map:
# - CAMPUS: can get +1 from mountains (22,11) and (21,15), +1 from geothermal at (21,13)
# - COMMERCIAL_HUB: +2 from river
# - INDUSTRIAL_ZONE: benefits from adjacent aqueduct/dam and districts
# - HOLY_SITE: benefits from mountains and forests
# - HARBOR: +2 from city center adjacency (on coast)
# - GOVERNMENT_PLAZA: counts as district for adjacency

# Non-specialty that help:
# - AQUEDUCT: +1 to adjacent Industrial Zone, must be adj to city center + mountain/river
# - DAM: +1 to adjacent Industrial Zone, must be on floodplains + river

# Let me try promising combinations
# Best specialty combos to try:
district_combos = [
    # High value combos - focus on adjacency-rich districts
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'HOLY_SITE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'ENTERTAINMENT_COMPLEX'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'HARBOR'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'HARBOR'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'GOVERNMENT_PLAZA', 'HARBOR'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'GOVERNMENT_PLAZA', 'THEATER_SQUARE'],
    ['CAMPUS', 'HOLY_SITE', 'INDUSTRIAL_ZONE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'ENTERTAINMENT_COMPLEX'],
    ['CAMPUS', 'INDUSTRIAL_ZONE', 'GOVERNMENT_PLAZA', 'COMMERCIAL_HUB'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'INDUSTRIAL_ZONE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'HOLY_SITE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'ENTERTAINMENT_COMPLEX'],
    ['CAMPUS', 'HOLY_SITE', 'HARBOR', 'COMMERCIAL_HUB'],
]

# Also consider non-specialty additions
# Aqueduct and Dam can be added on top of the 4 specialty districts

# For efficiency, let me try a focused approach:
# 1. Choose city center location
# 2. Determine available tiles within range 3
# 3. Try all combos of 4 specialty districts + optional aqueduct/dam

best_total = 0
best_placement = None
best_bonuses = None
best_city = None

# Candidate city center locations - should be on land
# Focus on central locations that have good tiles within range 3
city_candidates = [t for t in land_tiles]

print(f"Testing {len(city_candidates)} city locations...")

for cc in city_candidates:
    cx, cy = cc

    # Find tiles within range 3
    tiles_in_range_land = [t for t in land_tiles if t != cc and hex_distance(t[0], t[1], cx, cy) <= 3]
    tiles_in_range_coast = [t for t in coast_tiles if hex_distance(t[0], t[1], cx, cy) <= 3]

    if len(tiles_in_range_land) < 4:
        continue

    # Determine valid aqueduct tiles
    aqueduct_tiles = []
    nbs_cc = get_neighbors(cx, cy)
    for t in tiles_in_range_land:
        if t in nbs_cc:
            # Adjacent to city center - check water source
            if is_mountain(t):
                continue  # can't place on mountain
            has_source = False
            for nx, ny in get_neighbors(t[0], t[1]):
                if (nx, ny) in plots and is_mountain((nx, ny)):
                    has_source = True
            if tile_has_river(t[0], t[1]):
                has_source = True
            if has_source:
                aqueduct_tiles.append(t)

    # Determine valid dam tiles
    dam_tiles = [t for t in tiles_in_range_land if is_floodplains(t) and tile_has_river(t[0], t[1])]

    # Try each district combo
    for combo in district_combos:
        # For harbor combos, we need coast tiles
        has_harbor = 'HARBOR' in combo

        specialty_land = [d for d in combo if d != 'HARBOR']

        # Build tile pools
        if has_harbor:
            # Need to assign harbor to a coast tile
            for ht in tiles_in_range_coast:
                # Remaining specialty go on land
                remaining_districts = [d for d in combo if d != 'HARBOR']
                for land_combo in combinations(tiles_in_range_land, len(remaining_districts)):
                    for perm in permutations(remaining_districts):
                        placement = dict(zip(perm, land_combo))
                        placement['HARBOR'] = ht

                        # Validate all placements
                        valid = True
                        for dtype, tile in placement.items():
                            if not is_valid_placement(dtype, tile, {k:v for k,v in placement.items() if k != dtype}, cc):
                                valid = False
                                break
                        if not valid:
                            continue

                        # Also try adding aqueduct and/or dam
                        for extra_districts in [[], ]:
                            # Try without extras first
                            t, b = total_adjacency(placement, cc)
                            if t > best_total:
                                best_total = t
                                best_placement = dict(placement)
                                best_bonuses = dict(b)
                                best_city = cc
                                print(f"  New best: {t} at city {cc}, {b}")

                        # Try with aqueduct
                        for aq in aqueduct_tiles:
                            if aq in placement.values():
                                continue
                            p2 = dict(placement)
                            p2['AQUEDUCT'] = aq
                            valid = True
                            for dtype, tile in p2.items():
                                if not is_valid_placement(dtype, tile, {k:v for k,v in p2.items() if k != dtype}, cc):
                                    valid = False
                                    break
                            if valid:
                                t, b = total_adjacency(p2, cc)
                                if t > best_total:
                                    best_total = t
                                    best_placement = dict(p2)
                                    best_bonuses = dict(b)
                                    best_city = cc
                                    print(f"  New best with AQ: {t} at city {cc}, {b}")

                        # Try with dam
                        for dm in dam_tiles:
                            if dm in placement.values():
                                continue
                            p2 = dict(placement)
                            p2['DAM'] = dm
                            valid = True
                            for dtype, tile in p2.items():
                                if not is_valid_placement(dtype, tile, {k:v for k,v in p2.items() if k != dtype}, cc):
                                    valid = False
                                    break
                            if valid:
                                t, b = total_adjacency(p2, cc)
                                if t > best_total:
                                    best_total = t
                                    best_placement = dict(p2)
                                    best_bonuses = dict(b)
                                    best_city = cc
                                    print(f"  New best with DAM: {t} at city {cc}, {b}")

                        # Try with both aqueduct and dam
                        for aq in aqueduct_tiles:
                            if aq in placement.values():
                                continue
                            for dm in dam_tiles:
                                if dm in placement.values() or dm == aq:
                                    continue
                                p2 = dict(placement)
                                p2['AQUEDUCT'] = aq
                                p2['DAM'] = dm
                                valid = True
                                for dtype, tile in p2.items():
                                    if not is_valid_placement(dtype, tile, {k:v for k,v in p2.items() if k != dtype}, cc):
                                        valid = False
                                        break
                                if valid:
                                    t, b = total_adjacency(p2, cc)
                                    if t > best_total:
                                        best_total = t
                                        best_placement = dict(p2)
                                        best_bonuses = dict(b)
                                        best_city = cc
                                        print(f"  New best with AQ+DAM: {t} at city {cc}, {b}")
        else:
            # All on land
            for land_combo in combinations(tiles_in_range_land, len(combo)):
                for perm in permutations(combo):
                    placement = dict(zip(perm, land_combo))

                    valid = True
                    for dtype, tile in placement.items():
                        if not is_valid_placement(dtype, tile, {k:v for k,v in placement.items() if k != dtype}, cc):
                            valid = False
                            break
                    if not valid:
                        continue

                    t, b = total_adjacency(placement, cc)
                    if t > best_total:
                        best_total = t
                        best_placement = dict(placement)
                        best_bonuses = dict(b)
                        best_city = cc
                        print(f"  New best: {t} at city {cc}, {b}")

                    # Try with aqueduct
                    for aq in aqueduct_tiles:
                        if aq in placement.values():
                            continue
                        p2 = dict(placement)
                        p2['AQUEDUCT'] = aq
                        valid = True
                        for dtype, tile in p2.items():
                            if not is_valid_placement(dtype, tile, {k:v for k,v in p2.items() if k != dtype}, cc):
                                valid = False
                                break
                        if valid:
                            t, b = total_adjacency(p2, cc)
                            if t > best_total:
                                best_total = t
                                best_placement = dict(p2)
                                best_bonuses = dict(b)
                                best_city = cc
                                print(f"  New best with AQ: {t} at city {cc}, {b}")

