import sqlite3
import json
from itertools import combinations, permutations
import time

MAP_WIDTH = 44
MAP_HEIGHT = 26

conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cursor = conn.cursor()

cursor.execute("SELECT ID, TerrainType, IsImpassable FROM Plots ORDER BY ID")
plots = {}
for row in cursor.fetchall():
    pid = row[0]
    x = pid % MAP_WIDTH
    y = pid // MAP_WIDTH
    plots[(x, y)] = {'terrain': row[1], 'impassable': row[2]}

cursor.execute("SELECT ID, FeatureType FROM PlotFeatures")
features = {}
for row in cursor.fetchall():
    x = row[0] % MAP_WIDTH
    y = row[0] // MAP_WIDTH
    features[(x, y)] = row[1]

cursor.execute("SELECT * FROM PlotRivers")
rivers_raw = cursor.fetchall()
conn.close()

def get_neighbors(x, y):
    if y % 2 == 0:
        return [(x+1,y),(x-1,y),(x,y+1),(x-1,y+1),(x,y-1),(x-1,y-1)]
    else:
        return [(x+1,y),(x-1,y),(x+1,y+1),(x,y+1),(x+1,y-1),(x,y-1)]

river_edges = set()
for r in rivers_raw:
    pid = r[0]
    x = pid % MAP_WIDTH
    y = pid // MAP_WIDTH
    if y % 2 == 0:
        nb = {'NE':(x,y+1),'W':(x-1,y),'NW':(x-1,y+1)}
    else:
        nb = {'NE':(x+1,y+1),'W':(x-1,y),'NW':(x,y+1)}
    if r[1]: river_edges.add(frozenset({(x,y), nb['NE']}))
    if r[2]: river_edges.add(frozenset({(x,y), nb['W']}))
    if r[3]: river_edges.add(frozenset({(x,y), nb['NW']}))

def tile_has_river(x, y):
    for nx, ny in get_neighbors(x, y):
        if frozenset({(x,y),(nx,ny)}) in river_edges:
            return True
    return False

def hex_distance(x1, y1, x2, y2):
    def to_cube(x, y):
        cx = x - (y - (y & 1)) // 2
        cz = y
        cy = -cx - cz
        return cx, cy, cz
    c1 = to_cube(x1, y1)
    c2 = to_cube(x2, y2)
    return max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2]))

def is_land(tile):
    if tile not in plots:
        return False
    t = plots[tile]['terrain']
    return t not in ('TERRAIN_OCEAN', 'TERRAIN_COAST') and 'MOUNTAIN' not in t

def is_coast(tile):
    if tile not in plots:
        return False
    return plots[tile]['terrain'] == 'TERRAIN_COAST'

def is_mountain(tile):
    if tile not in plots:
        return False
    return 'MOUNTAIN' in plots[tile]['terrain']

def is_floodplains(tile):
    return features.get(tile, '') == 'FEATURE_FLOODPLAINS_PLAINS'

land_tiles = sorted([t for t in plots if is_land(t)])
coast_tiles = sorted([t for t in plots if is_coast(t)])

def calc_adjacency(district_type, tile, all_placed, city_center):
    """
    all_placed: dict of district_type -> tile (includes this district)
    """
    x, y = tile
    nbs = get_neighbors(x, y)

    adj_mountains = 0
    adj_geothermal = 0
    adj_reefs = 0
    adj_forests = 0
    adj_jungles = 0
    adj_districts = 0
    has_river = tile_has_river(x, y)
    adj_aqueduct = 0
    adj_dam = 0
    adj_city_center = 0
    adj_entertainment = 0
    adj_harbor = 0

    occupied = set(all_placed.values())
    occupied.add(city_center)

    for nx, ny in nbs:
        nt = (nx, ny)
        if nt not in plots:
            continue

        terrain = plots[nt]['terrain']
        feat = features.get(nt, '')

        if 'MOUNTAIN' in terrain:
            adj_mountains += 1

        # Features only count if the tile doesn't have a district/city on it
        if nt not in occupied:
            if feat == 'FEATURE_GEOTHERMAL_FISSURE':
                adj_geothermal += 1
            if feat == 'FEATURE_REEF':
                adj_reefs += 1
            if feat == 'FEATURE_FOREST':
                adj_forests += 1
            if feat == 'FEATURE_JUNGLE':
                adj_jungles += 1

        # Count adjacent districts (including city center)
        if nt == city_center:
            adj_city_center += 1
            adj_districts += 1

        for dtype, dtile in all_placed.items():
            if dtile == nt and dtype != district_type:
                adj_districts += 1
                if dtype == 'AQUEDUCT':
                    adj_aqueduct += 1
                elif dtype == 'DAM':
                    adj_dam += 1
                elif dtype == 'ENTERTAINMENT_COMPLEX':
                    adj_entertainment += 1
                elif dtype == 'HARBOR':
                    adj_harbor += 1

