import sqlite3
import json
from itertools import combinations, permutations
import time

MAP_WIDTH = 44
MAP_HEIGHT = 26

conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cursor = conn.cursor()

cursor.execute("SELECT ID, TerrainType, IsImpassable FROM Plots ORDER BY ID")
plots = {}
for row in cursor.fetchall():
    pid = row[0]
    x = pid % MAP_WIDTH
    y = pid // MAP_WIDTH
    plots[(x, y)] = {'terrain': row[1], 'impassable': row[2]}

cursor.execute("SELECT ID, FeatureType FROM PlotFeatures")
features = {}
for row in cursor.fetchall():
    x = row[0] % MAP_WIDTH
    y = row[0] // MAP_WIDTH
    features[(x, y)] = row[1]

cursor.execute("SELECT * FROM PlotRivers")
rivers_raw = cursor.fetchall()
conn.close()

def get_neighbors(x, y):
    if y % 2 == 0:
        return [(x+1,y),(x-1,y),(x,y+1),(x-1,y+1),(x,y-1),(x-1,y-1)]
    else:
        return [(x+1,y),(x-1,y),(x+1,y+1),(x,y+1),(x+1,y-1),(x,y-1)]

river_edges = set()
for r in rivers_raw:
    pid = r[0]
    x = pid % MAP_WIDTH
    y = pid // MAP_WIDTH
    if y % 2 == 0:
        nb = {'NE':(x,y+1),'W':(x-1,y),'NW':(x-1,y+1)}
    else:
        nb = {'NE':(x+1,y+1),'W':(x-1,y),'NW':(x,y+1)}
    if r[1]: river_edges.add(frozenset({(x,y), nb['NE']}))
    if r[2]: river_edges.add(frozenset({(x,y), nb['W']}))
    if r[3]: river_edges.add(frozenset({(x,y), nb['NW']}))

def tile_has_river(t):
    x, y = t
    for nx, ny in get_neighbors(x, y):
        if frozenset({(x,y),(nx,ny)}) in river_edges:
            return True
    return False

def hex_distance(x1, y1, x2, y2):
    def to_cube(x, y):
        cx = x - (y - (y & 1)) // 2
        cz = y
        cy = -cx - cz
        return cx, cy, cz
    c1 = to_cube(x1, y1)
    c2 = to_cube(x2, y2)
    return max(abs(c1[0]-c2[0]), abs(c1[1]-c2[1]), abs(c1[2]-c2[2]))

def is_land(tile):
    if tile not in plots:
        return False
    t = plots[tile]['terrain']
    return t not in ('TERRAIN_OCEAN', 'TERRAIN_COAST') and 'MOUNTAIN' not in t

def is_coast(tile):
    if tile not in plots:
        return False
    return plots[tile]['terrain'] == 'TERRAIN_COAST'

def is_mountain(tile):
    if tile not in plots:
        return False
    return 'MOUNTAIN' in plots[tile]['terrain']

def is_floodplains(tile):
    return features.get(tile, '') == 'FEATURE_FLOODPLAINS_PLAINS'

land_tiles = sorted([t for t in plots if is_land(t)])
coast_tiles = sorted([t for t in plots if is_coast(t)])

# Precompute neighbor sets and properties
neighbor_cache = {}
for t in plots:
    neighbor_cache[t] = get_neighbors(t[0], t[1])

river_tile_cache = {}
for t in plots:
    river_tile_cache[t] = tile_has_river(t)

mountain_set = set(t for t in plots if is_mountain(t))

def calc_adjacency(district_type, tile, all_placed, city_center):
    nbs = neighbor_cache[tile]
    occupied = set(all_placed.values())
    occupied.add(city_center)

    adj_mountains = 0
    adj_geothermal = 0
    adj_reefs = 0
    adj_forests = 0
    adj_jungles = 0
    adj_districts = 0
    adj_aqueduct = 0
    adj_dam = 0
    adj_city_center = 0
    adj_entertainment = 0
    adj_harbor = 0

    for nt in nbs:
        if nt not in plots:
            continue

        if nt in mountain_set:
            adj_mountains += 1

        if nt not in occupied:
            feat = features.get(nt, '')
            if feat == 'FEATURE_GEOTHERMAL_FISSURE':
                adj_geothermal += 1
            elif feat == 'FEATURE_REEF':
                adj_reefs += 1
            elif feat == 'FEATURE_FOREST':
                adj_forests += 1
            elif feat == 'FEATURE_JUNGLE':
                adj_jungles += 1

        if nt == city_center:
            adj_city_center += 1
            adj_districts += 1

        for dtype, dtile in all_placed.items():
            if dtile == nt and dtype != district_type:
                adj_districts += 1
                if dtype == 'AQUEDUCT':
                    adj_aqueduct += 1
                elif dtype == 'DAM':
                    adj_dam += 1
                elif dtype == 'ENTERTAINMENT_COMPLEX':
                    adj_entertainment += 1
                elif dtype == 'HARBOR':
                    adj_harbor += 1

    score = 0
    if district_type == 'CAMPUS':
        score = adj_mountains + adj_geothermal + adj_reefs + adj_jungles // 2 + adj_districts // 2
    elif district_type == 'HOLY_SITE':
        score = adj_mountains + adj_forests // 2 + adj_districts // 2
    elif district_type == 'THEATER_SQUARE':
        score = adj_entertainment + adj_districts // 2
    elif district_type == 'COMMERCIAL_HUB':
        score = (2 if river_tile_cache.get(tile, False) else 0) + adj_harbor * 2 + adj_districts // 2
    elif district_type == 'HARBOR':
        score = adj_city_center * 2 + adj_districts // 2
    elif district_type == 'INDUSTRIAL_ZONE':
        score = adj_aqueduct + adj_dam + adj_districts // 2
    elif district_type == 'ENTERTAINMENT_COMPLEX':
        score = adj_districts // 2
    elif district_type == 'GOVERNMENT_PLAZA':
        score = adj_districts // 2
    elif district_type == 'ENCAMPMENT':
        score = adj_districts // 2
    return score

def total_adjacency(placement, city_center):
    total = 0
    bonuses = {}
    for dtype, tile in placement.items():
        bonus = calc_adjacency(dtype, tile, placement, city_center)
        bonuses[dtype] = bonus
        total += bonus
    return total, bonuses

# Now use a greedy + local search approach instead of brute force
# Step 1: For each city center, identify the best tiles for each district type
# Step 2: Use greedy placement, then improve with swaps

def get_available_tiles(cc, placed_tiles):
    """Get tiles available for placement (land, in range, not occupied)."""
    cx, cy = cc
    return [t for t in land_tiles if t != cc and t not in placed_tiles
            and hex_distance(t[0], t[1], cx, cy) <= 3]

def get_available_coast(cc, placed_tiles):
    cx, cy = cc
    return [t for t in coast_tiles if t not in placed_tiles
            and hex_distance(t[0], t[1], cx, cy) <= 3]

def score_tile_for_district(dtype, tile, existing_placement, cc):
    """Score a tile for a district given existing placements."""
    test_placement = dict(existing_placement)
    test_placement[dtype] = tile
    return calc_adjacency(dtype, tile, test_placement, cc)

# Let's try a smarter approach: enumerate all assignments of tiles to district types
# but limit the search to the most promising tiles for each type

def solve_for_city(cc, specialty_combo, include_aqueduct=False, include_dam=False):
    """Try to optimally place districts for a given city center and combo."""
    cx, cy = cc

    all_land = [t for t in land_tiles if t != cc and hex_distance(t[0], t[1], cx, cy) <= 3]
    all_coast = [t for t in coast_tiles if hex_distance(t[0], t[1], cx, cy) <= 3]

    nbs_cc = set(neighbor_cache[cc])

    # Build list of (district_type, valid_tiles)
    districts_to_place = []
    for d in specialty_combo:
        if d == 'HARBOR':
            valid = all_coast
        elif d == 'ENCAMPMENT':
            valid = [t for t in all_land if t not in nbs_cc]
        else:
            valid = list(all_land)
        districts_to_place.append((d, valid))

    if include_aqueduct:
        aq_valid = [t for t in all_land if t in nbs_cc and (
            river_tile_cache.get(t, False) or
            any(n in mountain_set for n in neighbor_cache.get(t, []))
        )]
        if aq_valid:
            districts_to_place.append(('AQUEDUCT', aq_valid))
        else:
            include_aqueduct = False

    if include_dam:
        dam_valid = [t for t in all_land if is_floodplains(t) and river_tile_cache.get(t, False)]
        if dam_valid:
            districts_to_place.append(('DAM', dam_valid))
        else:
            include_dam = False

    n = len(districts_to_place)
    if n == 0:
        return 0, {}, {}

    # For small search spaces, do exhaustive
    # For large ones, use greedy + local search

    total_combinations = 1
    for _, valid in districts_to_place:
        total_combinations *= len(valid)

    best_score = 0
    best_placement = {}
    best_bonuses = {}

    if n <= 6 and total_combinations < 5000000:
        # Recursive exhaustive search with pruning
        def search(idx, placement, used_tiles):
            nonlocal best_score, best_placement, best_bonuses

            if idx == n:
                t, b = total_adjacency(placement, cc)
                if t > best_score:
                    best_score = t
                    best_placement = dict(placement)
                    best_bonuses = dict(b)
                return

            dtype, valid_tiles = districts_to_place[idx]
            for tile in valid_tiles:
                if tile in used_tiles:
                    continue
                placement[dtype] = tile
                used_tiles.add(tile)
                search(idx + 1, placement, used_tiles)
                del placement[dtype]
                used_tiles.discard(tile)

        search(0, {}, set())
    else:
        # Greedy + local search
        # Greedy: place each district on the best available tile
        placement = {}
        used = set()

        for dtype, valid in districts_to_place:
            best_tile = None
            best_tile_score = -1
            for tile in valid:
                if tile in used:
                    continue
                s = score_tile_for_district(dtype, tile, placement, cc)
                if s > best_tile_score:
                    best_tile_score = s
                    best_tile = tile
            if best_tile:
                placement[dtype] = best_tile
                used.add(best_tile)

        if len(placement) == n:
            best_score, best_bonuses = total_adjacency(placement, cc)
            best_placement = dict(placement)

        # Local search: try swapping tiles between districts
        improved = True
        while improved:
            improved = False
            for i in range(n):
                for j in range(i+1, n):
                    d1, _ = districts_to_place[i]
                    d2, _ = districts_to_place[j]
                    if d1 not in best_placement or d2 not in best_placement:
                        continue
                    # Try swap
                    t1, t2 = best_placement[d1], best_placement[d2]
                    test = dict(best_placement)
                    test[d1] = t2
                    test[d2] = t1
                    # Check validity
                    valid = True
                    if d1 == 'HARBOR' and not is_coast(t2): valid = False
                    if d2 == 'HARBOR' and not is_coast(t1): valid = False
                    if d1 == 'ENCAMPMENT' and t2 in nbs_cc: valid = False
                    if d2 == 'ENCAMPMENT' and t1 in nbs_cc: valid = False
                    if d1 == 'AQUEDUCT' and (t2 not in nbs_cc or not (river_tile_cache.get(t2,False) or any(n in mountain_set for n in neighbor_cache.get(t2,[])))): valid = False
                    if d2 == 'AQUEDUCT' and (t1 not in nbs_cc or not (river_tile_cache.get(t1,False) or any(n in mountain_set for n in neighbor_cache.get(t1,[])))): valid = False
                    if d1 == 'DAM' and (not is_floodplains(t2) or not river_tile_cache.get(t2,False)): valid = False
                    if d2 == 'DAM' and (not is_floodplains(t1) or not river_tile_cache.get(t1,False)): valid = False
                    if not valid:
                        continue
                    ts, bs = total_adjacency(test, cc)
                    if ts > best_score:
                        best_score = ts
                        best_placement = test
                        best_bonuses = bs
                        improved = True

            # Also try moving each district to a different tile
            for i in range(n):
                dtype, valid = districts_to_place[i]
                if dtype not in best_placement:
                    continue
                for tile in valid:
                    if tile in best_placement.values():
                        continue
                    test = dict(best_placement)
                    test[dtype] = tile
                    ts, bs = total_adjacency(test, cc)
                    if ts > best_score:
                        best_score = ts
                        best_placement = test
                        best_bonuses = bs
                        improved = True

    return best_score, best_placement, best_bonuses

# Main search
best_total = 0
best_placement = None
best_bonuses = None
best_city = None

specialty_combos = [
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'HOLY_SITE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'ENTERTAINMENT_COMPLEX'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HOLY_SITE', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'GOVERNMENT_PLAZA', 'THEATER_SQUARE'],
    ['CAMPUS', 'HOLY_SITE', 'INDUSTRIAL_ZONE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'INDUSTRIAL_ZONE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'HOLY_SITE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'HARBOR', 'ENTERTAINMENT_COMPLEX'],
    ['CAMPUS', 'HOLY_SITE', 'HARBOR', 'INDUSTRIAL_ZONE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'ENTERTAINMENT_COMPLEX', 'THEATER_SQUARE'],
    ['CAMPUS', 'COMMERCIAL_HUB', 'ENTERTAINMENT_COMPLEX', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'INDUSTRIAL_ZONE', 'ENTERTAINMENT_COMPLEX', 'COMMERCIAL_HUB'],
    ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'ENTERTAINMENT_COMPLEX'],
    ['CAMPUS', 'HOLY_SITE', 'ENTERTAINMENT_COMPLEX', 'THEATER_SQUARE'],
    ['CAMPUS', 'HOLY_SITE', 'THEATER_SQUARE', 'GOVERNMENT_PLAZA'],
    ['CAMPUS', 'HOLY_SITE', 'THEATER_SQUARE', 'COMMERCIAL_HUB'],
]

start = time.time()
promising_cities = []
for cc in land_tiles:
    cx, cy = cc
    in_range = sum(1 for t in land_tiles if t != cc and hex_distance(t[0], t[1], cx, cy) <= 3)
    if in_range >= 6:
        promising_cities.append(cc)

print(f"Testing {len(promising_cities)} city centers...")

for cc in promising_cities:
    for combo in specialty_combos:
        # Try without extras
        s, p, b = solve_for_city(cc, combo)
        if s > best_total:
            best_total = s
            best_placement = p
            best_bonuses = b
            best_city = cc
            print(f"New best: {s} city={cc} combo={combo} bonuses={b}")

        # Try with aqueduct
        s, p, b = solve_for_city(cc, combo, include_aqueduct=True)
        if s > best_total:
            best_total = s
            best_placement = p
            best_bonuses = b
            best_city = cc
            print(f"New best+AQ: {s} city={cc} combo={combo} bonuses={b}")

        # Try with dam
        s, p, b = solve_for_city(cc, combo, include_dam=True)
        if s > best_total:
            best_total = s
            best_placement = p
            best_bonuses = b
            best_city = cc
            print(f"New best+DAM: {s} city={cc} combo={combo} bonuses={b}")

        # Try with both
        s, p, b = solve_for_city(cc, combo, include_aqueduct=True, include_dam=True)
        if s > best_total:
            best_total = s
            best_placement = p
            best_bonuses = b
            best_city = cc
            print(f"New best+AQ+DAM: {s} city={cc} combo={combo} bonuses={b}")

    elapsed = time.time() - start
    if elapsed > 500:
        print(f"Time limit approaching!")
        break

elapsed = time.time() - start
print(f"\nDone in {elapsed:.1f}s")
print(f"\nFINAL BEST:")
print(f"City center: {best_city}")
print(f"Placements: {best_placement}")
print(f"Bonuses: {best_bonuses}")
print(f"Total: {best_total}")

# Verify all adjacency calculations
print("\nVerification:")
for dtype, tile in best_placement.items():
    bonus = calc_adjacency(dtype, tile, best_placement, best_city)
    print(f"  {dtype} at {tile}: adjacency = {bonus}")
    # Print what contributes
    nbs = neighbor_cache[tile]
    occupied = set(best_placement.values())
    occupied.add(best_city)
    for nt in nbs:
        if nt not in plots:
