        info = []
        if nt in mountain_set:
            info.append("mountain")
        if nt == best_city:
            info.append("city_center")
        for dt, dt_tile in best_placement.items():
            if dt_tile == nt and dt != dtype:
                info.append(f"district:{dt}")
        if nt not in occupied:
            feat = features.get(nt, '')
            if feat:
                info.append(f"feature:{feat}")
        if info:
            river_str = " [RIVER]" if frozenset({tile, nt}) in river_edges else ""
            print(f"    neighbor {nt}: {', '.join(info)}{river_str}")
    if river_tile_cache.get(tile, False):
        print(f"    tile has river edge(s)")
